    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> last;
    bool found = false;
    for (int i = 0; i < n; i++) {
        auto it = last.find(a[i]);
        if (it != last.end() && i - it->second <= k) {
            found = true;
            break;
        }
        last[a[i]] = i;
    }
    cout << (found ? "yes" : "no") << "\n";

